      "content": "{\n  \"name\": \"dsh-blender\",\n  \"version\": \"0.2.4\",\n  \"description\": \"DeepSeek Harness Blender production, reconstruction, validation, and export plugin\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/CheshireJCat/blender.git\"\n  },\n  \"homepage\": \"https://github.com/CheshireJCat/blender#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/CheshireJCat/blender/issues\"\n  },\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"bin\": {\n    \"dsh-blender-setup\": \"scripts/setup-analysis.js\"\n  },\n  \"exports\": {\n    \".\": \"./index.js\"\n  },\n  \"files\": [\n    \"index.js\",\n    \"cordis.patch.yml\",\n    \"lib\",\n    \"scripts\",\n    \"skills\",\n    \"requirements-analysis.txt\",\n    \"LICENSE\",\n    \"NOTICE\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"CHANGELOG.md\",\n    \"docs/compatibility-v0.2.3.md\"\n  ],\n  \"scripts\": {\n    \"prepack\": \"node scripts/clean-package.js\",\n    \"setup:analysis\": \"node scripts/setup-analysis.js\",\n    \"test\": \"node --test\",\n    \"test:blender\": \"RUN_BLENDER_TESTS=1 node --test test/blender.integration.test.js\",\n    \"test:helpers\": \"RUN_HELPER_TESTS=1 node --test test/helpers.integration.test.js\",\n    \"test:dsh\": \"node test-support/dsh-profile-smoke.js\",\n    \"validate\": \"node scripts/validate-package.js\"\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh-plugin\",\n    \"blender\",\n    \"3d-modeling\",\n    \"agent-skill\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"compatibility\": {\n      \"dsh\": \"0.2.0-rc.2 || 0.2.1-alpha.1 || 0.2.1-alpha.2\",\n      \"dshReleases\": {\n        \"0.2.0-rc.2\": \"compatible\",\n        \"0.2.1-alpha.1\": \"compatible\",\n        \"0.2.1-alpha.2\": \"compatible\"\n      },\n      \"dshOperations\": {\n        \"0.2.0-rc.2\": {\n          \"install\": \"passed\",\n          \"start\": \"passed