      "path": "cordis.patch.yml",
      "content": "- insert:\n    - id: blender-modeling\n      name: dsh-blender\n      config:\n        blenderExecutable: blender\n        analysisPythonExecutable: ''\n        timeoutMs: 180000\n        helperTimeoutMs: 120000\n        maxOutputChars: 20000\n        restrictToWorkspace: true\n        enablePython: true\n        enableHelpers: true\n        enableMaintenanceHelpers: false\n        registerSkill: true\n        registerModuleSkills: true\n"
