      "content": "const inputFile = (name, flag, options = {}) => ({ name, flag, type: 'path', pathKind: 'input-file', ...options })\nconst inputDir = (name, flag, options = {}) => ({ name, flag, type: 'path', pathKind: 'input-dir', ...options })\nconst inputPath = (name, flag, options = {}) => ({ name, flag, type: 'path', pathKind: 'input-path', ...options })\nconst outputFile = (name, flag, options = {}) => ({ name, flag, type: 'path', pathKind: 'output-file', ...options })\nconst outputDir = (name, flag, options = {}) => ({ name, flag, type: 'path', pathKind: 'output-dir', ...options })\nconst value = (name, flag, type = 'string', options = {}) => ({ name, flag, type, ...options })\n\nexport const HELPER_CATALOG = [\n  {\n    name: 'animation-contact-sheet',\n    module: 'animation-quality-gate',\n    description: 'Combine rendered animation frames into a labeled contact sheet and flag large frame-to-frame visual jumps.',\n    runtime: 'python',\n    dependencies: ['Pillow'],\n    script: 'references/modules/animation-quality-gate/scripts/animation_contact_sheet.py',\n    arguments: [\n      { name: 'frames', flag: '--frames', type: 'path-array', pathKind: 'input-file', required: true },\n      outputFile('out_image', '--out-image', { required: true }),\n      outputFile('out_report', '--out-report', { required: true }),\n      value('cols', '--cols', 'integer'),\n    ],\n  },\n  {\n    name: 'atlas-region-detector',\n    module: 'atlas-uv-fitting',\n    description: 'Detect occupied regions in a texture atlas and write measurable UV-region candidates.',\n    runtime: 'python',\n    dependencies: ['opencv-python-headless', 'numpy'],\n    script: 'references/modules/atlas-uv-fitting/scripts/atlas_region_detector.py',\n    arguments: [\n      inputFile('image', '--image', { required: true }),\n      outputFile('out', '--out', { required: true }),\n      value('mode', '--mode', 'string', { choices: ['auto', 'alpha', 'bright_on_dark', 'dark_on_bright'] }),\n      value('min_area', '--min-area', 'integer'),\n      value('pad', '--pad', 'integer'),\n    ],\n  },\n  {\n    name: 'atlas-region-mapper',\n    module: 'atlas-uv-fitting',\n    description: 'Match segmented source parts to detected atlas regions and emit ranked mapping candidates.',\n    runtime: 'python',\n    dependencies: [],\n    script: 'references/modules/atlas-uv-fitting/scripts/atlas_region_mapper.py',\n    arguments: [\n      inputFile('parts', '--parts', { required: true }),\n      inputFile('regions', '--regions', { required: true }),\n      outputFile('out', '--out', { required: true }),\n      value('max_candidates', '--max-candidates', 'integer'),\n    ],\n  },\n  {\n    name: 'skill-graph-audit',\n    module: 'blender-skill-harmonizer',\n    description: 'Audit a Blender skill graph and report unresolved references or missing harmonization.',\n    runtime: 'python',\n    dependencies: [],\n    maintenance: true,\n    script: 'references/modules/blender-skill-harmonizer/scripts/skill_graph_audit.py',\n    arguments: [\n      inputDir('plugin_root', '--plugin-root'),\n      outputFile('out', '--out', { required: true }),\n    ],\n  },\n  {\n    name: 'surface-texture-coverage-audit',\n    module: 'closed-surface-uv-coverage',\n    description: 'Audit mesh UV layers, material slots, and image-texture coverage inside a Blender scene.',\n    runtime: 'blender',\n    dependencies: [],\n    requiresBlend: true,\n    script: 'references/modules/closed-surface-uv-coverage/scripts/surface_texture_coverage_audit.py',\n    arguments: [\n      value('objects', '--objects', 'string-array'),\n      outputFile('out', '--out'),\n    ],\n  },\n  {\n    name: 'mask-to-mesh-recipe',\n    module: 'contour-to-mesh',\n    description: 'Extract a source contour and emit a deterministic mesh recipe plus optional Blender Python.',\n    runtime: 'python',\n    dependencies: ['opencv-python-headless', 'numpy', 'scipy'],\n    script: 'references/modules/contour-to-mesh/scripts/mask_t