 'references/modules/fit-repair-optimizer/scripts/fit_repair_queue.py',\n    arguments: [\n      inputFile('fit_report', '--fit-report', { required: true }),\n      inputFile('texture_lighting_report', '--texture-lighting-report'),\n      outputFile('out', '--out', { required: true }),\n      outputFile('method_md', '--method-md'),\n    ],\n  },\n  {\n    name: 'landmark-fit-report',\n    module: 'landmark-fit-repair',\n    description: 'Compare named source and product landmarks and report pixel deltas against a tolerance.',\n    runtime: 'python',\n    dependencies: [],\n    script: 'references/modules/landmark-fit-repair/scripts/landmark_fit_report.py',\n    arguments: [\n      inputFile('source', '--source', { required: true }),\n      inputFile('product', '--product', { required: true }),\n      outputFile('out', '--out', { required: true }),\n      value('tolerance_px', '--tolerance-px', 'number'),\n    ],\n  },\n  {\n    name: 'view-constraint-report',\n    module: 'multiview-constraint-solver',\n    description: 'Detect contradictory shared-axis dimensions across front, side, back, and top view bboxes.',\n    runtime: 'python',\n    dependencies: [],\n    script: 'references/modules/multiview-constraint-solver/scripts/view_constraint_report.py',\n    arguments: [\n      inputFile('input', '--input', { required: true }),\n      outputFile('out', '--out', { required: true }),\n      value('tolerance', '--tolerance', 'number'),\n    ],\n  },\n  {\n    name: 'multiview-fit-report',\n    module: 'multiview-fit-loop',\n    description: 'Compare registered front, side, back, and top template/render pairs and save overlays plus fit metrics.',\n    runtime: 'python',\n    dependencies: ['opencv-python-headless', 'numpy'],\n    script: 'references/modules/multiview-fit-loop/scripts/multiview_fit_report.py',\n    arguments: [\n      inputFile('front_template', '--front-template'),\n      inputFile('front_render', '--front-render'),\n      inputFile('side_template', '--